#!/usr/bin/env bash
set -u
echo "== 解包三维记忆图谱 =="
mkdir -p /tmp/xm-mg && rm -rf /tmp/xm-mg/site && mkdir -p /tmp/xm-mg/site
echo '' | base64 -d > /tmp/xm-mg/u.tgz
tar -xzf /tmp/xm-mg/u.tgz -C /tmp/xm-mg/site
echo "== 覆盖到站点 =="
sudo cp -r /tmp/xm-mg/site/. /var/www/xinmo-site/
echo "== 校验 =="
ls -l /var/www/xinmo-site/assets/js/vendor/three.min.js /var/www/xinmo-site/assets/js/memory-graph.js /var/www/xinmo-site/memory-graph.css 2>/dev/null || true
grep -c 'MemoryGraphView' /var/www/xinmo-site/memory.html
grep -c 'graph-view' /var/www/xinmo-site/assets/js/memory-app.js
echo "== DONE =="
